import{_ as i,r as s,o as h,c as l,a,b as t,d as o,e as r}from"./chunks/framework.8NMv9ABN.js";const v=JSON.parse('{"title":"Knives","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/knives.md","filePath":"en/tools/knives.md"}'),c={name:"en/tools/knives.md"};function d(g,e,u,p,m,f){const n=s("Screenshot");return h(),l("div",null,[e[0]||(e[0]=a("h1",{id:"knives",tabindex:"-1"},[t("Knives "),a("a",{class:"header-anchor",href:"#knives","aria-label":'Permalink to "Knives"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Knives is a price movement scanner. It watches every ticker on every exchange you enable, and surfaces a card the moment one of them moves further than a threshold you set — up or down.",-1)),e[2]||(e[2]=a("p",null,[t("All of its readings are based on the "),a("strong",null,"current 5-minute candle"),t(". A ticker appears because "),a("em",null,"this"),t(" candle has moved, not because of a 24-hour figure.")],-1)),o(n,{src:"knives",alt:"The Knives window showing ticker cards with mini charts",caption:"The Knives window"}),e[3]||(e[3]=r('<h2 id="reading-the-window" tabindex="-1">Reading the window <a class="header-anchor" href="#reading-the-window" aria-label="Permalink to &quot;Reading the window&quot;">​</a></h2><h3 id="before-anything-triggers" tabindex="-1">Before anything triggers <a class="header-anchor" href="#before-anything-triggers" aria-label="Permalink to &quot;Before anything triggers&quot;">​</a></h3><p>When nothing has crossed a threshold yet, the window shows its listening state instead of cards:</p><ul><li><strong>Listening</strong> — a pulsing label, followed by one entry per enabled exchange showing that exchange&#39;s icon, its trigger percentage, and its volume threshold if the volume filter is on for it. This is a live summary of what Knives is currently armed to catch.</li><li><strong>No exchanges armed</strong> — every exchange is disabled. Nothing can trigger. Enable at least one in the settings panel.</li></ul><h3 id="a-ticker-card" tabindex="-1">A ticker card <a class="header-anchor" href="#a-ticker-card" aria-label="Permalink to &quot;A ticker card&quot;">​</a></h3><p>Each card has a header row and a mini chart beneath it.</p><p>In the header, left to right:</p><ul><li><strong>Exchange icons</strong> — which exchanges the ticker is listed on. Hovering one shows <code>Listed on &lt;exchange&gt;</code>. These can be hidden entirely; see <a href="#exchange-icons">Show icons</a>.</li><li><strong>NEW badge</strong> — the ticker was listed within the last 60 seconds. The badge is colored by the exchange that listed it, and hovering shows which one. It disappears once the ticker is more than a minute old.</li><li><strong>Ticker symbol</strong> — click it to copy the symbol to your clipboard. It briefly reads <code>Copied!</code> to confirm.</li></ul><p>On the right:</p><ul><li><strong>Volume</strong> — the current 5m candle&#39;s volume in USD. Only shown when volume display is on; see <a href="#show-volume-in-tickers">Show volume</a>.</li><li><strong>Price change</strong> — the current 5m candle&#39;s percent change, signed.</li><li><strong>Expand button</strong> — opens the ticker fullscreen.</li></ul><h3 id="what-the-colors-mean" tabindex="-1">What the colors mean <a class="header-anchor" href="#what-the-colors-mean" aria-label="Permalink to &quot;What the colors mean&quot;">​</a></h3><p>A card colors its percentage <em>and</em> its header stripe green or red once the current candle&#39;s move has reached that exchange&#39;s <strong>% Change</strong> trigger. Below the trigger, the reading stays neutral.</p><p>So the color is not &quot;price is up&quot; — it is &quot;this move is at or beyond the level you asked to be told about&quot;. A card can be present and still show a neutral reading if it has since pulled back below the threshold.</p><div class="warning custom-block"><p class="custom-block-title">Direction is judged per exchange</p><p>The threshold used for coloring is the one belonging to the exchange the card came from. If you have set different <strong>% Change</strong> values per exchange, two cards showing the same percentage can be colored differently.</p></div><h3 id="fullscreen" tabindex="-1">Fullscreen <a class="header-anchor" href="#fullscreen" aria-label="Permalink to &quot;Fullscreen&quot;">​</a></h3><p>The expand button opens a single ticker at full window size with a larger chart and a timeframe selector offering <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code> and <code>1w</code>.</p><p>You can star timeframes in the dropdown to pin them as a quick-access row next to the selector. Favourites are shared with the other tools&#39; fullscreen chart views.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open the <strong>Knives</strong> tab in the main window.</p>',19)),o(n,{src:"knives-settings",alt:"Knives display, chart data priority and exchange icon settings",caption:"Knives settings — display, priority, icons"}),e[4]||(e[4]=r('<h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-tickers" tabindex="-1">Max tickers <a class="header-anchor" href="#max-tickers" aria-label="Permalink to &quot;Max tickers&quot;">​</a></h4><p>How many ticker cards the window shows at once. Range <strong>3 to 66</strong>, default 12.</p><h4 id="show-volume-in-tickers" tabindex="-1">Show volume in tickers <a class="header-anchor" href="#show-volume-in-tickers" aria-label="Permalink to &quot;Show volume in tickers&quot;">​</a></h4><p>Displays the volume figure in each card&#39;s header.</p><p>This toggle is <strong>forced on and locked</strong> whenever the volume filter is enabled for any exchange — if you are filtering by volume, Knives always shows you the volume it filtered on. Its description changes to <code>Always on when volume filter is enabled</code> to indicate this. Turn every exchange&#39;s volume filter off to get the toggle back.</p><h3 id="chart-data-priority" tabindex="-1">Chart data priority <a class="header-anchor" href="#chart-data-priority" aria-label="Permalink to &quot;Chart data priority&quot;">​</a></h3><h4 id="exchange-priority" tabindex="-1">Exchange priority <a class="header-anchor" href="#exchange-priority" aria-label="Permalink to &quot;Exchange priority&quot;">​</a></h4><p>A drag-to-reorder list of all five exchanges. Drag an entry up or down with the mouse to change its rank.</p><p>This controls <strong>which exchange supplies the mini chart&#39;s candles</strong> when a ticker is listed on more than one. The first exchange in the list that is enabled and has the ticker wins.</p><p>It does not affect which exchanges can trigger an alert — that is the per-exchange <strong>Enable</strong> toggle below.</p><h3 id="exchange-icons" tabindex="-1">Exchange icons <a class="header-anchor" href="#exchange-icons" aria-label="Permalink to &quot;Exchange icons&quot;">​</a></h3><h4 id="show-icons" tabindex="-1">Show icons <a class="header-anchor" href="#show-icons" aria-label="Permalink to &quot;Show icons&quot;">​</a></h4><p>Shows or hides the exchange icons on every ticker card. Off gives you a denser, plainer card; on tells you at a glance where a ticker trades.</p><h3 id="per-exchange-settings" tabindex="-1">Per-exchange settings <a class="header-anchor" href="#per-exchange-settings" aria-label="Permalink to &quot;Per-exchange settings&quot;">​</a></h3><p>Knives has an identical settings block for each of <strong>Bybit</strong>, <strong>Binance</strong>, <strong>Gate.io</strong>, <strong>OKX</strong> and <strong>Hyperliquid</strong>. Every exchange is configured independently — thresholds, volume filters and enablement are all per exchange.</p><h4 id="enable-exchange" tabindex="-1">Enable &lt;exchange&gt; <a class="header-anchor" href="#enable-exchange" aria-label="Permalink to &quot;Enable \\&lt;exchange\\&gt;&quot;">​</a></h4><p>Whether Knives receives alerts from this exchange at all. Off means the exchange is not scanned, and its tickers cannot produce cards. All five default to on.</p><p>Disabling an exchange greys out the rest of that block.</p><h4 id="change" tabindex="-1">% Change <a class="header-anchor" href="#change" aria-label="Permalink to &quot;% Change&quot;">​</a></h4><p>The move, on the current 5m candle, that triggers an alert for this exchange. Range <strong>2% to 10%</strong> in 0.5% steps, default 2%.</p><p>This is the primary threshold. It also decides when a card&#39;s reading turns green or red.</p><h4 id="high-threshold" tabindex="-1">High threshold <a class="header-anchor" href="#high-threshold" aria-label="Permalink to &quot;High threshold&quot;">​</a></h4><p>The level that counts as a major move for this exchange, and the point at which the <a href="#price-change-sound">price change sound</a> fires. Range <strong>2% to 10%</strong> in 0.5% steps, default 6%.</p><div class="warning custom-block"><p class="custom-block-title">This slider is additive</p><p>The value displayed next to the slider is <strong>% Change + High threshold</strong>, not the slider&#39;s own value — with % Change at 2% and the slider at 6%, the label reads <strong>8.0%</strong>, and that is where the sound fires.</p><p>Read the label, not the slider position.</p></div><p>Because it is additive, raising <strong>% Change</strong> also raises the major-movement level. Set the base trigger first, then tune this on top of it.</p><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Filters this exchange&#39;s tickers by trading volume, so low-liquidity moves never reach you. Off by default.</p><p>Turning this on for any exchange also forces <a href="#show-volume-in-tickers">Show volume in tickers</a> on.</p><h4 id="volume-threshold" tabindex="-1">Volume threshold <a class="header-anchor" href="#volume-threshold" aria-label="Permalink to &quot;Volume threshold&quot;">​</a></h4><p>The minimum volume, in USD on the current 5m candle, a ticker needs before it can produce a card. Range <strong>$100K to $10M</strong> in $100K steps, default $1M.</p><p>Greyed out unless the volume filter is enabled for this exchange.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="new-ticker-sound" tabindex="-1">New ticker sound <a class="header-anchor" href="#new-ticker-sound" aria-label="Permalink to &quot;New ticker sound&quot;">​</a></h4><p>Plays a sound when a new ticker enters the window.</p><h4 id="price-change-sound" tabindex="-1">Price change sound <a class="header-anchor" href="#price-change-sound" aria-label="Permalink to &quot;Price change sound&quot;">​</a></h4><p>Plays a sound when a move reaches this exchange&#39;s major-movement level — the figure shown beside its <a href="#high-threshold">High threshold</a> slider.</p><p>It fires at most once per ticker per candle, so a ticker that keeps moving inside the same 5m candle won&#39;t sound repeatedly.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Both sounds are global to Knives rather than per exchange, are independent of each other, and are each rate-limited to one play every 2 seconds.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/manual/en/tools/alerts.html">Alerts</a> — cross-exchange price deviations rather than single-exchange moves</li><li><a href="/manual/en/tools/monitor.html">Monitor</a> — a ranked view of the whole market instead of a trigger-based feed</li><li><a href="/manual/en/customize/chart-colors.html">Charts &amp; drawing</a> — candle colors used by the mini charts</li></ul>',41))])}const w=i(c,[["render",d]]);export{v as __pageData,w as default};
